int huge_memory_walk(unsigned long addr, unsigned long end, struct mm_walk *walk) {
    while (addr < end) {
        struct page *page;
        unsigned long mask = huge_page_mask(hstate_vma(walk->vma));
        unsigned long aligned_addr = addr & mask;

        if (aligned_addr < addr) {
            aligned_addr = addr;
        }

        if (aligned_addr >= end) {
            break;
        }

        page = follow_huge_addr(walk->vma, aligned_addr, 0);
        if (IS_ERR_OR_NULL(page)) {
            int err = PTR_ERR(page);
            if (err == -EFAULT) {
                addr = ALIGN(addr, HPAGE_PMD_SIZE);
                continue;
            }
            return err;
        }

        int ret = walk->fn(walk, addr, aligned_addr, page);
        if (ret < 0) {
            return ret;
        }

        addr = aligned_addr + huge_page_size(hstate_vma(walk->vma));
    }

    return 0;
}

int walk_huge_page_range(unsigned long addr, unsigned long end, struct mm_walk *walk) {
    unsigned long next;
    int ret = 0;

    while (addr < end) {
        struct vm_area_struct *vma = walk->vma;
        pgprot_t pgprot = vma->vm_page_prot;
        struct hstate *h = hstate_vma(vma);
        unsigned long hmask = h->huge_page_mask;
        unsigned long boundary = (addr + ~hmask) & hmask;

        next = (addr + PAGE_SIZE) & hmask;
        if (next > end)
            next = end;

        if (walk->pte_hole) {
            ret = walk->pte_hole(walk, addr, next);
            if (ret)
                break;
        }

        if (walk->pte_entry) {
            ret = walk->pte_entry((pte_t *) addr, addr, next, walk);
            if (ret)
                break;
        }

        addr = next;
    }

    return ret;
}

#include <linux/hugetlb.h>
#include <linux/mm.h>

int walk_huge_page_range(unsigned long addr, unsigned long end, struct mm_walk *walk) {
    unsigned long start = addr;
    int ret = 0;

    while (start < end) {
        struct hstate *h;
        unsigned long mask;

        h = hstate_file(walk->vma->vm_file->f_mapping);
        if (!h)
            return -EINVAL;

        mask = huge_page_mask(h);
        start = (start + mask) & ~mask;
        if (start >= end)
            break;

        ret = walk->hugetlb_entry(walk, start, start + HPAGE_SIZE(h), walk->private);
        if (ret)
            break;

        start += HPAGE_SIZE(h);
    }

    return ret;
}

int walk_huge_pages(unsigned long addr, unsigned long end, struct mm_walk *walk) {
    struct hstate *h;
    unsigned long mask;

    for (h = hstate_first(); h; h = hstate_next(h)) {
        mask = huge_page_mask(h);
        if (mask == 0)
            continue;

        while (addr < end) {
            unsigned long next = (addr + mask) & ~(mask - 1);
            if (next > end)
                next = end;

            if (walk->vma && walk->vma->vm_start > addr)
                break;

            if (walk->fn) {
                int ret = walk->fn(addr, next, walk);
                if (ret < 0)
                    return ret;
            }

            addr = next;
        }
    }

    return 0;
}

int walk_huge_page_range(unsigned long addr, unsigned long end, struct mm_walk *walk) {
    unsigned long start = addr;
    unsigned long next;
    int ret = 0;

    while (start < end) {
        struct hstate *h = hstate_file(walk->vma->vm_file->f_mapping);
        unsigned long mask = huge_page_mask(h);
        unsigned long align_start = ALIGN(start, mask);

        if (align_start >= end) {
            break;
        }

        next = ALIGN(align_start + 1, mask);
        if (next > end) {
            next = end;
        }

        ret = walk->vma->vm_ops->fault(walk->vma, walk->address, 0, 0, 0, NULL);
        if (ret < 0) {
            break;
        }

        start = next;
    }

    return ret;
}
